<script setup lang="ts">import { onMounted, ref } from 'vue'; import { Cpu, Plus, ShieldCheck, Trash2 } from 'lucide-vue-next'; import PageHeader from '../components/PageHeader.vue'; import EmptyState from '../components/EmptyState.vue'; import { useResourcesStore } from '../stores/resources'; import { useAppStore } from '../stores/app'; import { api } from '../api/client'; const store = useResourcesStore(); const app = useAppStore(); const show = ref(false); const form = ref({ name:'', base_url:'', model:'', secret_reference:'', enabled:true }); onMounted(() => store.loadProviders()); async function add() { if (!form.value.name || !form.value.base_url || !form.value.model) return; try { const item = await api.createProvider({ ...form.value, provider_type:'openai_compatible', timeout_s:30 }); store.providers.push(item); show.value = false; form.value = { name:'', base_url:'', model:'', secret_reference:'', enabled:true }; app.toast('提供商已添加') } catch (e) { app.toast(e instanceof Error ? e.message : '添加失败') } } async function remove(id:number) { if (!confirm('确定删除这个提供商吗？')) return; try { await api.deleteProvider(id); store.providers = store.providers.filter(p => p.id !== id); app.toast('提供商已删除') } catch (e) { app.toast(e instanceof Error ? e.message : '删除失败') } }</script>
<template><section class="page-content"><PageHeader eyebrow="AI 配置" title="模型提供商" description="为 AI 助手选择可用的模型连接。密钥只通过后端 secret_reference 管理。"><button class="button button-primary" @click="show = !show"><Plus :size="16" />添加提供商</button></PageHeader><form v-if="show" class="form-card panel" @submit.prevent="add"><div class="form-grid"><label>名称<input v-model="form.name" required placeholder="例如：校园助手模型" /></label><label>模型<input v-model="form.model" required placeholder="模型名称" /></label><label class="wide-field">Base URL<input v-model="form.base_url" type="url" required placeholder="https://api.example.com/v1" /></label><label class="wide-field">Secret reference<input v-model="form.secret_reference" placeholder="env:YOUR_API_KEY" /><small>不会在 UI 或响应中显示 secret 内容。</small></label></div><div class="form-actions"><button type="button" class="button button-secondary" @click="show = false">取消</button><button class="button button-primary">保存提供商</button></div></form><section class="provider-list" v-if="store.providers.length"><article v-for="provider in store.providers" :key="provider.id" class="panel provider-card"><div class="provider-icon"><Cpu :size="19" /></div><div class="provider-body"><div class="provider-title"><h3>{{ provider.name }}</h3><span class="status-badge" :class="provider.enabled ? 'success' : 'muted'">{{ provider.enabled ? '可用' : '已停用' }}</span></div><p>{{ provider.model }}</p><small>{{ provider.base_url }}</small></div><div class="provider-safe"><ShieldCheck :size="15" />密钥由后端托管</div><button class="icon-button danger-button" :aria-label="`删除${provider.name}`" @click="remove(provider.id)"><Trash2 :size="17" /></button></article></section><section v-else class="panel"><EmptyState title="还没有模型提供商" description="添加后，AI 助手才会有可用的模型后端。" /></section></section></template>
